using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Shipping;

public sealed class ShippingFeeAcceptanceTests
{
    private static int Fee(int payable, LoyaltyTier tier, bool express = false) =>
        new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(payable, tier, express));

    [Theory]
    [InlineData(4_999, LoyaltyTier.Bronze, 490)]
    [InlineData(5_000, LoyaltyTier.Bronze, 0)]
    [InlineData(4_999, LoyaltyTier.Silver, 490)]
    public void S11_StandardShippingIsFreeFromFiftyEurosPayable(int payable, LoyaltyTier tier, int fee) =>
        Assert.Equal(fee, Fee(payable, tier));

    [Theory]
    [InlineData(LoyaltyTier.Gold)]
    [InlineData(LoyaltyTier.Platinum)]
    public void S12_GoldAndPlatinumNeverPayStandardShipping(LoyaltyTier tier) =>
        Assert.Equal(0, Fee(1_000, tier));

    [Theory]
    [InlineData(10_000, LoyaltyTier.Bronze, 990)]
    [InlineData(1_000, LoyaltyTier.Gold, 990)]
    [InlineData(1_000, LoyaltyTier.Platinum, 0)]
    public void S13_ExpressShippingCostsNinetyNineCentsFreeForPlatinumOnly(int payable, LoyaltyTier tier, int fee) =>
        Assert.Equal(fee, Fee(payable, tier, express: true));
}
