namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int CapCents = 2_000;

    public static int LoyaltyPartCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(subtotalCents * RatePercent(tier) / 100, CapCents);

    public static int DiscountCents(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyPart = LoyaltyPartCents(subtotalCents, tier);
        var promoPart = PromoCodePolicy.DiscountCents(promoCode, subtotalCents - loyaltyPart);
        return Math.Min(loyaltyPart + promoPart, subtotalCents);
    }

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => 0
    };
}

namespace CheckoutPricing.Domain;

public static class PromoCodePolicy
{
    private const int Welcome5Cents = 500;
    private const int Summer10MaximumCents = 1_500;

    public static int DiscountCents(string? promoCode, int amountLeftCents)
    {
        if (string.Equals(promoCode, "WELCOME5", StringComparison.OrdinalIgnoreCase))
        {
            return Welcome5Cents;
        }

        return string.Equals(promoCode, "SUMMER10", StringComparison.OrdinalIgnoreCase)
            ? Math.Min(amountLeftCents / 10, Summer10MaximumCents)
            : 0;
    }
}

namespace CheckoutPricing.Domain;

public static class ShippingFeePolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int FeeCents(int payableTotalCents, LoyaltyTier tier, bool express) =>
        express ? ExpressFeeCents(tier) : StandardFeeCents(payableTotalCents, tier);

    private static int ExpressFeeCents(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents();

    private static int ExpressFeeCents() => ShippingFeePolicy.ExpressFeeCentsValue;

    private static int StandardFeeCents(int payableTotalCents, LoyaltyTier tier) =>
        tier >= LoyaltyTier.Gold || payableTotalCents >= FreeStandardFromCents ? 0 : StandardFeeCentsValue;

